package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Sets {@code namesakeCount} to the number of existing owners sharing the same firstName and
 * lastName as the owner being created, compared case-insensitively. Runs before the owner is
 * saved, so {@link OwnerRepository#findAll()} sees only the owners that existed before this
 * create.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = owner.getFirstName();
        String lastName = owner.getLastName();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName != null && lastName != null
                    && firstName.equalsIgnoreCase(existing.getFirstName())
                    && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}
===== CountHousehold.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Sets {@code householdSize} to the number of members the owner's household has after this create:
 * every existing owner sharing the same household plus the owner being created. The household is now
 * the deterministic {@link HouseholdId} derived from the last name and postcode, so two owners belong
 * to the same household exactly when they share a {@code householdId} — the same rule duplicate
 * detection ({@link RejectDuplicateOwner}) uses. Runs before the owner is saved, so
 * {@link OwnerRepository#findAll()} sees only the owners that existed before this create, which are then
 * counted alongside this one.
 */
public class CountHousehold {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = HouseholdId.of(owner.getLastName(), owner.getPostcode());
        int count = 1;
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))) {
                count++;
            }
        }
        owner.setHouseholdSize(count);
    }
}
===== AssignMembershipLevel.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the {@code membershipPoints} score and the derived numeric {@code membershipLevel} at
 * creation time. Points start at {@code 0} and accrue: {@code 2} when the owner has an email,
 * {@code 1} when {@code namesakeCount} is {@code 0}, {@code 2} for a household of {@code 3} or more
 * (from {@code householdSize}), and {@code 3} for a tenure of at least one elapsed fiscal year
 * (fiscal years, starting 1 July, between the owner's {@code registrationDate} and the current
 * server date). Points map to a level as {@code 1} (0-1 points), {@code 2} (2-3), {@code 3} (4-5)
 * and {@code 4} (6 or more). Runs after {@link CountNamesakes} and {@link CountHousehold} so both
 * counts are already set.
 */
public class AssignMembershipLevel {

    /** Elapsed fiscal years at or above which the owner qualifies for the tenure points. */
    private static final int TENURE_THRESHOLD_FISCAL_YEARS = 1;

    /** Household size at or above which the household points are awarded. */
    private static final int HOUSEHOLD_THRESHOLD = 3;

    public void service(@Val Owner owner) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += 2;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            points += 1;
        }
        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= HOUSEHOLD_THRESHOLD) {
            points += 2;
        }
        if (tenureFiscalYears(owner) >= TENURE_THRESHOLD_FISCAL_YEARS) {
            points += 3;
        }
        owner.setMembershipPoints(points);
        owner.setMembershipLevel(levelForPoints(points));
    }

    private static int levelForPoints(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    private static int tenureFiscalYears(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return 0;
        }
        return FiscalYear.elapsed(registrationDate, LocalDate.now());
    }
}
===== CapMembershipLevel.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Caps the owner's {@code membershipLevel} so a new owner cannot outrank their household: the level
 * may be at most one above the current maximum {@code membershipLevel} among the existing members of
 * the same household. The household is the deterministic {@link HouseholdId} derived from last name
 * and postcode, matching {@link CountHousehold} and {@link RejectDuplicateOwner}. Runs after
 * {@link AssignMembershipLevel} has set the raw level and before the owner is saved, so
 * {@link OwnerRepository#findAll()} sees only the owners that existed before this create. With no
 * existing household member the level is left unchanged.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        Integer level = owner.getMembershipLevel();
        if (level == null) {
            return;
        }
        String householdId = HouseholdId.of(owner.getLastName(), owner.getPostcode());
        Integer maxExisting = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (!householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))) {
                continue;
            }
            Integer existingLevel = existing.getMembershipLevel();
            if (existingLevel != null && (maxExisting == null || existingLevel > maxExisting)) {
                maxExisting = existingLevel;
            }
        }
        if (maxExisting != null && level > maxExisting + 1) {
            owner.setMembershipLevel(maxExisting + 1);
        }
    }
}
