===== IdempotencyStore.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.springframework.stereotype.Component;

/**
 * Remembers which {@code Idempotency-Key} values have already produced an owner, mapping each
 * seen key to the id of the owner it originally created. Shared singleton so the mapping
 * survives across requests. A repeated create carrying an already-seen key can therefore return
 * the originally created owner instead of creating a duplicate.
 */
@Component
public class IdempotencyStore {

    private final Map<String, Integer> keyToOwnerId = new ConcurrentHashMap<>();

    /** The id of the owner previously created under {@code key}, or {@code null} if unseen. */
    public Integer find(String key) {
        return this.keyToOwnerId.get(key);
    }

    /** Records that {@code key} created the owner with {@code ownerId} (first write wins). */
    public void record(String key, int ownerId) {
        this.keyToOwnerId.putIfAbsent(key, ownerId);
    }
}
===== AddressNormalizer.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Canonical form of an owner's postal {@code address}, applied whenever an owner is created. Trims
 * leading/trailing whitespace, collapses runs of whitespace to a single space, upper-cases, and expands
 * common street-type abbreviations as whole words ({@code ST -> STREET}, {@code RD -> ROAD},
 * {@code AVE -> AVENUE}). So {@code '  12  main  st '} becomes {@code '12 MAIN STREET'} and
 * {@code '7 elm ave'} becomes {@code '7 ELM AVENUE'}. A {@code null} or whitespace-only address
 * normalizes to the empty string.
 *
 * <p>This is the single normalized form used everywhere an address matters: it is what
 * {@link NormalizeAddress} stores on the request (so it is persisted and returned) and what
 * {@link RequireOwnerFields} tests for blankness. (The household id is keyed on last name and
 * postcode, not the address — see {@link HouseholdId}.)
 */
public final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    public static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder result = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                result.append(' ');
            }
            result.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return result.toString();
    }
}
===== Locality.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Derives an owner's {@code locality}: the canonical region. The postcode is preferred — a postcode
 * that falls in a known range fixes the region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099, via
 * {@link PostcodeRanges}) regardless of the city. Only when the postcode is absent or in no known
 * range does it fall back to the fixed city-to-region table (Sydney -> NSW, Melbourne -> VIC,
 * Brisbane -> QLD). Any city not in the table (including a null or blank city) derives
 * {@code "UNKNOWN"}. This returns the same region for known cities but disambiguates cities that
 * share a name. The mapping is pinned so it is stable across requests and needs no persisted column.
 */
public final class Locality {

    /** City -> canonical region; anything not listed derives locality "UNKNOWN". */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    static final String UNKNOWN = "UNKNOWN";

    private Locality() {
    }

    /** The region for {@code city} from the fixed table alone, or {@code "UNKNOWN"} when unlisted. */
    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, UNKNOWN);
    }

    /**
     * Derives the region, preferring the postcode: the region whose range contains the postcode wins;
     * otherwise the city-to-region table decides.
     */
    public static String of(String city, String postcode) {
        String fromPostcode = PostcodeRanges.regionFor(postcode);
        if (fromPostcode != null) {
            return fromPostcode;
        }
        return CITY_REGION.getOrDefault(city, UNKNOWN);
    }

    /**
     * The locality read back off the owner's {@code customerCode} identity ({@code <REGION>-<HASH8>},
     * see {@link AssignCustomerCode}): the REGION segment before the first {@code '-'}. Returns
     * {@code "UNKNOWN"} when the code is null or carries no region segment, so locality now flows from
     * the same region-and-hash identity rather than being derived independently.
     */
    public static String ofCustomerCode(String customerCode) {
        if (customerCode == null) {
            return UNKNOWN;
        }
        int dash = customerCode.indexOf('-');
        if (dash <= 0) {
            return UNKNOWN;
        }
        return customerCode.substring(0, dash);
    }
}
===== PostcodeRanges.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Fixed region-to-postcode-range table used to validate an owner's postcode against the region
 * derived from its city (see {@link Locality}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region
 * with no entry (including {@code "UNKNOWN"}) has no range, so any 4-digit postcode is accepted.
 */
public final class PostcodeRanges {

    /** Region -> inclusive 4-digit postcode range {low, high}. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private PostcodeRanges() {
    }

    /** The inclusive {low, high} range for {@code region}, or {@code null} when the region is unknown. */
    public static int[] forRegion(String region) {
        return REGION_POSTCODES.get(region);
    }

    /**
     * The region whose range contains {@code postcode}, or {@code null} when the postcode is absent,
     * not four digits, or in no known range.
     */
    public static String regionFor(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }
}
===== TelephoneE164.java =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Converts a telephone number to E.164 form. A leading {@code '+'} and country code are kept when
 * present; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
 * from the national digits. Spaces, dashes and brackets are stripped. The result must have 8 to 15
 * digits after the {@code '+'}, otherwise it cannot form valid E.164.
 *
 * <p>The national-number length is also checked against the country code: {@code '+61'} requires
 * exactly 9 national digits and {@code '+1'} requires exactly 10. A wrong length for the country
 * cannot form a valid number and is rejected (a 400 at the endpoint).
 */
final class TelephoneE164 {

    private TelephoneE164() {
    }

    /**
     * Normalizes {@code raw} to E.164, throwing {@link InvalidTelephoneException} when it cannot.
     */
    static String normalize(String raw) throws InvalidTelephoneException {
        String e164 = normalizeOrNull(raw);
        if (e164 == null) {
            throw new InvalidTelephoneException(raw);
        }
        return e164;
    }

    /**
     * Normalizes {@code raw} to E.164, returning {@code null} when it cannot form valid E.164.
     */
    static String normalizeOrNull(String raw) {
        if (raw == null) {
            return null;
        }
        // Strip spaces, dashes and brackets, keeping a leading '+' and the digits.
        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
        String national;
        if (cleaned.startsWith("+")) {
            national = cleaned.substring(1);
            if (!national.matches("\\d+")) {
                return null;
            }
        }
        else {
            if (!cleaned.matches("\\d+")) {
                return null;
            }
            // No country code: assume +61 and drop a single leading '0' from the national digits.
            if (cleaned.startsWith("0")) {
                cleaned = cleaned.substring(1);
            }
            national = "61" + cleaned;
        }
        if (national.length() < 8 || national.length() > 15) {
            return null;
        }
        // National-number length per country code: '+61' => 9 national digits, '+1' => 10.
        if (national.startsWith("61")) {
            if (national.length() - 2 != 9) {
                return null;
            }
        }
        else if (national.startsWith("1")) {
            if (national.length() - 1 != 10) {
                return null;
            }
        }
        return "+" + national;
    }
}
===== IdentityKey.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Derives an owner's {@code identityKey}: the single value all duplicate detection is now expressed
 * through. It is the full lower-case hex {@link Sha256} of {@code normalizedTelephone + '|' +
 * lowerEmail + '|' + soundex(lastName)}, where the telephone is normalized to E.164 the same way as
 * {@link NormalizeTelephone}/{@link TelephoneE164}, the email is trimmed and lower-cased (empty when
 * absent or blank, the same form as {@link NormalizeEmail}), and the surname component is
 * {@link Soundex} of the last name. Because the telephone is part of the key, two members of the same
 * household — same {@code soundex(lastName)} and postcode but different telephones — derive different
 * identityKeys and are not a hard duplicate; the postcode is no longer part of the key, so it is the
 * soft-match ({@link DetectPossibleDuplicate}) that pairs such owners.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(String telephone, String email, String lastName) {
        String normalizedTelephone = TelephoneE164.normalizeOrNull(telephone);
        if (normalizedTelephone == null) {
            normalizedTelephone = telephone == null ? "" : telephone.trim();
        }
        String normalizedEmail = (email == null || email.isBlank())
                ? "" : email.trim().toLowerCase(Locale.ROOT);
        String soundex = Soundex.of(lastName);
        return Sha256.hex(normalizedTelephone + "|" + normalizedEmail + "|" + soundex);
    }
}
